?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Safeguarding · <?=$escape($brandName)?></title><style>body{margin:0;background:#f3f2ed;color:#1a2939;font:15px/1.6 system-ui}main{max-width:1000px;margin:35px auto;padding:18px}.panel{background:white;border:1px solid #ddd;padding:20px;margin:18px 0}.field{display:grid;gap:6px;margin:13px 0}input,select,textarea{font:inherit;padding:10px;border:1px solid #bbc4cd;width:100%;box-sizing:border-box}.button{background:#17283a;color:white;border:0;padding:11px 16px}.error{background:#fff0ee;padding:12px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #ddd}</style><body><header class="panel"><?=$escape($brandName)?> · <a href="/admin">Administration</a></header><main><p>RESTRICTED SAFEGUARDING · NOT AN EMERGENCY SERVICE</p><?php if($error!==''):?><p class="error"><?=$escape($error)?></p><?php endif;?>
<?php if($mode==='report'):?><h1>Submit confidential report</h1><p>Reporter access ends at acknowledgement. Do not include identity-document numbers, full birth dates, passwords, payment secrets or raw evidence.</p><form class="panel" method="post" action="/admin/safeguarding/reports"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><div class="field"><label>Category</label><select name="category"><?php foreach(['consent_concern','coercion_or_exploitation','trafficking_concern','minor_safety_concern','nonconsensual_content','threat_or_harassment','privacy_or_data_risk','other'] as $v):?><option value="<?=$escape($v)?>"><?=$escape($v)?></option><?php endforeach;?></select></div><div class="field"><label>Severity</label><select name="severity"><?php foreach(['low','medium','high','critical'] as $v):?><option><?=$escape($v)?></option><?php endforeach;?></select></div><div class="field"><label>Opaque related record reference</label><input name="subject_reference" maxlength="160"></div><div class="field"><label>Summary</label><input name="summary" minlength="20" maxlength="300" required></div><div class="field"><label>Details</label><textarea name="details" minlength="30" maxlength="5000" required></textarea></div><div class="field"><label>Assigned safeguarding specialist</label><select name="specialist_id" required><?php foreach($specialists as $s):?><option value="<?=$escape($s['id'])?>"><?=$escape($s['email'])?></option><?php endforeach;?></select></div><button class="button">Submit report</button></form>
<?php elseif($mode==='acknowledgement'):?><h1>Report received</h1><section class="panel">Case reference: <strong><?=$escape($caseReference??'')?></strong><p>Case contents are restricted to the assigned specialist. This is not an emergency hotline.</p></section>
<?php elseif($mode==='detail'):?><h1><?=$escape($case['case_reference']??'Case')?></h1><section class="panel"><p><?=$escape($case['category']??'')?> · <?=$escape($case['severity']??'')?> · <?=$escape($case['status']??'')?></p><h2><?=$escape($case['summary']??'')?></h2><p><?=nl2br($escape($case['details']??''))?></p><p>Related record: <?=$escape($case['subject_reference']??'')?></p></section><form class="panel" method="post" action="/admin/safeguarding/cases/<?=$escape($case['id'])?>/transition"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><select name="status"><?php foreach(['triaged','investigating','action_required','resolved','closed'] as $v):?><option><?=$escape($v)?></option><?php endforeach;?></select><textarea name="reason" minlength="10" maxlength="1000" required placeholder="Reason for transition"></textarea><button class="button">Record transition</button></form><?php foreach(($case['events']??[]) as $event):?><p><?=$escape($event['event_key'])?> · <?=$escape($event['created_at'])?> — <?=$escape($event['note']??'')?></p><?php endforeach;?>
<?php elseif($mode==='governance'):?>
<h1>Safeguarding governance · metadata only</h1>
<section class="panel"><h2>Encrypted backup retention policy</h2>
<?php if($backupPolicy!==null):?><p>Policy <strong><?=$escape($backupPolicy['policy_version'])?></strong> · expiry <?=$escape($backupPolicy['expiry_days'])?> days · encrypted backups <?=$backupPolicy['encrypted_backups']?'yes':'no'?> · approved by <?=$escape($backupPolicy['approver_email'])?> · <?=$escape($backupPolicy['approved_at'])?></p><?php else:?><p>No backup expiry policy has been approved.</p><?php endif;?>
<form method="post" action="/admin/safeguarding/governance/backup-policy"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><div class="field"><label>Backup expiry days</label><input type="number" name="expiry_days" min="1" max="3650" required></div><div class="field"><label>Policy version</label><input name="policy_version" minlength="3" maxlength="64" required></div><div class="field"><label>Approval reason</label><textarea name="reason" minlength="20" maxlength="500" required></textarea></div><button class="button">Approve encrypted backup policy</button></form>
</section>
<section class="panel"><h2>Category retention schedules</h2><p>Retention schedules are activated only when the encrypted-backup policy and an independent Vault restore verification share the same policy version. Retention days are extended by the backup expiry period before cryptographic erasure.</p>
<form method="post" action="/admin/safeguarding/governance/retention-policy"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><div class="field"><label>Case category</label><select name="category"><?php foreach(['consent_concern','coercion_or_exploitation','trafficking_concern','minor_safety_concern','nonconsensual_content','threat_or_harassment','privacy_or_data_risk','other'] as $v):?><option value="<?=$escape($v)?>"><?=$escape($v)?></option><?php endforeach;?></select></div><div class="field"><label>Retention days</label><input type="number" name="retention_days" min="1" max="3650" required></div><div class="field"><label>Legal basis reference</label><input name="legal_basis_reference" minlength="5" maxlength="190" required></div><div class="field"><label>Policy version (must match backup policy)</label><input name="policy_version" minlength="3" maxlength="64" required></div><label><input type="checkbox" name="enabled" value="1"> Enable this category schedule</label><div class="field"><label>Reason</label><textarea name="reason" minlength="20" maxlength="500" required></textarea></div><button class="button">Save retention schedule</button></form>
<table><thead><tr><th>Category</th><th>Days</th><th>Version</th><th>Enabled</th><th>Updated by</th></tr></thead><tbody><?php foreach($retentionPolicies as $p):?><tr><td><?=$escape($p['category'])?></td><td><?=$escape($p['retention_days'])?></td><td><?=$escape($p['policy_version'])?></td><td><?=(int)$p['enabled']?'Yes':'No'?></td><td><?=$escape($p['updated_by_email'])?></td></tr><?php endforeach;?></tbody></table>
</section>
<section class="panel"><h2>Independent Vault restore verification</h2><p>After restoring the database and Vault snapshot in a controlled restore environment, verify that every active case key still decrypts its stored ciphertext and that orphan keys are reconciled. The backup reference is stored as a hash; only the manifest SHA-256 is retained.</p>
<form method="post" action="/admin/safeguarding/governance/restore-verification"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><div class="field"><label>Backup reference (opaque)</label><input name="backup_reference" minlength="8" maxlength="256" required></div><div class="field"><label>Restore manifest SHA-256</label><input name="manifest_sha256" pattern="[a-f0-9]{64}" minlength="64" maxlength="64" required></div><div class="field"><label>Policy version</label><input name="policy_version" minlength="3" maxlength="64" required></div><button class="button">Verify Vault restore and record evidence</button></form>
<table><thead><tr><th>Policy</th><th>Manifest SHA-256</th><th>Active keys verified</th><th>Orphans destroyed</th><th>Verified by</th><th>Time</th></tr></thead><tbody><?php foreach($restoreVerifications as $v):?><tr><td><?=$escape($v['policy_version'])?></td><td><?=$escape($v['manifest_sha256'])?></td><td><?=$escape($v['active_keys_verified'])?></td><td><?=$escape($v['orphan_keys_destroyed'])?></td><td><?=$escape($v['verifier_email'])?></td><td><?=$escape($v['verified_at'])?></td></tr><?php endforeach;?></tbody></table>
</section>
<section class="panel"><h2>Case governance register · metadata only</h2><table><thead><tr><th>Reference</th><th>Category</th><th>Status</th><th>Legal hold</th><th>Action</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=$escape($item['case_reference'])?></td><td><?=$escape($item['category'])?> · <?=$escape($item['severity'])?></td><td><?=$escape($item['status'])?></td><td><?=(int)$item['legal_hold']?'Active':'None'?></td><td>
<?php if(($item['status']??'')!=='closed'):?><form method="post" action="/admin/safeguarding/governance/<?=$escape($item['id'])?>/reassign"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><label>Reassign to specialist (current assignee loses access)</label><select name="specialist_id" required><option value="">Choose eligible specialist</option><?php foreach(($specialists??[]) as $specialist):?><?php if($specialist['id']!==$item['assigned_specialist_id']):?><option value="<?=$escape($specialist['id'])?>"><?=$escape($specialist['email'])?></option><?php endif;?><?php endforeach;?></select><textarea name="reason" minlength="20" maxlength="1000" required placeholder="Reason for reassignment"></textarea><button class="button">Reassign case</button></form><?php endif;?>
<?php if((int)$item['legal_hold']):?><form method="post" action="/admin/safeguarding/governance/<?=$escape($item['id'])?>/release"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><input name="reason" minlength="20" maxlength="1000" required><button class="button">Release hold</button></form><?php else:?><form method="post" action="/admin/safeguarding/governance/<?=$escape($item['id'])?>/hold"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><input name="reason" minlength="20" maxlength="1000" required><button class="button">Place hold</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<?php else:?><h1>Assigned safeguarding cases</h1><section class="panel"><table><thead><tr><th>Reference</th><th>Category</th><th>Severity</th><th>Status</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><a href="/admin/safeguarding/cases/<?=$escape($item['id'])?>"><?=$escape($item['case_reference'])?></a></td><td><?=$escape($item['category'])?></td><td><?=$escape($item['severity'])?></td><td><?=$escape($item['status'])?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?></main></body></html>
